// Derived u8/decimal input; generated by verification/compact-write/derive.py.
// Release source and dependency source remain unchanged.

pub fn release_compact_u8(value: u8, buffer: &mut [u8]) -> usize {
    lexical_write_integer::compact::Compact::compact(value, 10, buffer)
}

pub fn decimal_u8(self_value: u8, buffer: &mut [u8]) -> usize {
    // NOTE: We do not have to validate the buffer length because `copy_to_dst` is
    // safe.
    let mut digits: [u8; 128] = [0u8; 128];
    let mut index = digits.len();

    // Decode all but the last digit.
    let radix = 10u8;
    let mut value = self_value;
    while value >= radix {
        let r = value % radix;
        value /= radix;
        index -= 1;
        digits[index] = digit_to_char(r as u32);
    }

    // Decode last digit.
    let r = value;
    index -= 1;
    digits[index] = digit_to_char(r as u32);
    let slc = &digits[index..];
    let len = slc.len();
    buffer[..len].copy_from_slice(slc);
    len
}

fn digit_to_char(digit: u32) -> u8 {
    const TABLE: [u8; 36] = [
        b'0', b'1', b'2', b'3', b'4', b'5', b'6', b'7', b'8', b'9', b'A', b'B', b'C', b'D', b'E',
        b'F', b'G', b'H', b'I', b'J', b'K', b'L', b'M', b'N', b'O', b'P', b'Q', b'R', b'S', b'T',
        b'U', b'V', b'W', b'X', b'Y', b'Z',
    ];
    debug_assert!(digit < 36, "digit_to_char() invalid character.");
    TABLE[digit as usize]
}
